def priority(item: float, bins: np.ndarray) -> np.ndarray:
    feasible = bins >= item
    if not np.any(feasible):
        return np.full_like(bins, -np.inf)
    mean_remaining = np.mean(bins[feasible])
    priorities = np.where(feasible, -np.abs(bins - mean_remaining), -np.inf)
    return priorities

